package de.fit.framework.generation;
import de.fit.framework.api.*;import de.fit.framework.domain.*;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component public class HilfsmittelGenerator{public HilfsmittelCaseData generate(HilfsmittelScenario s){List<PositionData> ps=new ArrayList<>();int number=1;for(PositionRequest r:s.positions()){List<TerminData> ts=new ArrayList<>();LocalDateTime first=s.prescribedOn().atTime(9,0);for(int i=0;i<r.appointments();i++){LocalDateTime from=first.plusDays(i);ts.add(new TerminData(i+1,from,from.plusMinutes(r.durationMinutes()),r.durationMinutes()));}ps.add(new PositionData(number++,ts.get(0).startsAt().toLocalDate(),ts.get(ts.size()-1).endsAt().toLocalDate(),ts));}return new HilfsmittelCaseData(null,s.gender(),s.age(),s.prescribedOn(),s.coPaymentExempt(),ps);}}
